with cleaned as (select id, session_id, event_type, event_time, hour(event_time) as event_time_hour, coalesce(page, 'UNKNOWN') as resolved_page from web_events where event_time >= timestamp '2023-03-30 04:00:00'), prev_events as (select *, lag(event_time) over (partition by event_type order by event_time, id) as prev_event_time from cleaned), with_gaps as (select *, case when prev_event_time is null or event_time > prev_event_time + interval '14' day then 1 else 0 end as new_group_flag from prev_events), islands as (select *, sum(new_group_flag) over (partition by event_type order by event_time, id rows between unbounded preceding and current row) as session_id_2 from with_gaps) select case when session_id_2 >= 7 then 'PREMIUM' else 'STANDARD' end as session_id_2_tier, percentile_approx(session_id_2, array(0.25, 0.5, 0.75)) as session_id_2_quartiles, sum(new_group_flag) filter (where event_type = 'click') as click_total_new_group_flag, approx_percentile(new_group_flag, 0.5) as new_group_flag_p50 from islands group by 1;
